from functools import cache
from taf.ul.ue.sim.env_setup.settings import PACKAGE_NAME


IS_REGISTERED = False


def is_dry_run():
    try:
        current_context = get_robot_context()
        if current_context is not None and current_context.dry_run:
            return True
    except Exception:
        pass
    return False


def get_robot_context():
    try:
        from robot.running.context import EXECUTION_CONTEXTS  # type: ignore[import-untyped]

        return EXECUTION_CONTEXTS.current
    except (ImportError, ModuleNotFoundError):
        pass
    return None


@cache
def get_telemetry_instance():
    global IS_REGISTERED
    if IS_REGISTERED is False and not is_dry_run():
        from taf.ul.telemetry import register  # type: ignore[import-untyped]

        IS_REGISTERED = True
        return register(PACKAGE_NAME)
